def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    if v2 == 0:
        return None
    value = (v1 / v2) * 100
    return {
        "value": value,
        "trace": {
            "numerator": v1,
            "denominator": v2,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
